function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(51501);
var T0=Date.now();/*Signature edition*/
var LAM=2,MU=3,C=1,N=2000;
var free=[],busyT=0,waits=[];
for(var s=0;s<C;s++)free.push(0);
var t=0;
for(var i=0;i<N;i++){
  t+=-Math.log(1-R())/LAM;
  var s=0;for(var k=1;k<C;k++)if(free[k]<free[s])s=k;
  var start=Math.max(t,free[s]),svc=-Math.log(1-R())/MU;
  free[s]=start+svc;busyT+=svc;waits.push(start-t);
}
var avg=waits.reduce(function(a,b){return a+b;},0)/waits.length;
var span=Math.max.apply(null,free);
console.log(JSON.stringify({id:"JAH-APX51S-000001",ok:true,metrics:{arrivals:N,served:N,avg_wait_s:+avg.toFixed(4),utilization:+(busyT/(C*span)).toFixed(4),span_s:+span.toFixed(2)},ms:Date.now()-T0}));

